	@Test
	void inlinesLeftBindingsIntoOptionalRightInput() {
		BindingSetAssignment left = new BindingSetAssignment();
		MapBindingSet row = new MapBindingSet();
		row.addBinding("s", iri("urn:left"));
		left.setBindingSets(List.of(row));
		StatementPattern right = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		LeftJoin optional = new LeftJoin(left, right);

		getOptimizer().optimize(optional, new SimpleDataset(), EmptyBindingSet.getInstance());

		assertThat(right.getSubjectVar().getValue()).isEqualTo(iri("urn:left"));
	}

	@Test
	void invalidatesPriorValuesAfterExtensionOverwrite() {
		BindingSetAssignment input = new BindingSetAssignment();
		MapBindingSet row = new MapBindingSet();
		row.addBinding("x", iri("urn:old"));
		input.setBindingSets(List.of(row));
		Extension overwrite = new Extension(input,
				new ExtensionElem(new ValueConstant(iri("urn:new")), "x"));
		Extension use = new Extension(overwrite, new ExtensionElem(Var.of("x"), "y"));

		getOptimizer().optimize(use, new SimpleDataset(), EmptyBindingSet.getInstance());

		Var yExpr = (Var) use.getElements().getFirst().getExpr();
		assertThat(yExpr.getValue()).isEqualTo(iri("urn:new"));
	}

	@Override
	public QueryOptimizer getOptimizer() {
		return new BindingSetAssignmentInlinerOptimizer();
	}

	private static List<BindingSet> evaluate(TupleExpr expression, TripleSource tripleSource) throws Exception {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(tripleSource, null);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}

	private static final class StatementListTripleSource extends EmptyTripleSource {
		private final List<Statement> statements;

		private StatementListTripleSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			Iterator<Statement> matches = statements.stream()
					.filter(statement -> (subject == null || subject.equals(statement.getSubject()))
							&& (predicate == null || predicate.equals(statement.getPredicate()))
							&& (object == null || object.equals(statement.getObject())))
					.toList()
					.iterator();
			return new CloseableIteratorIteration<>(matches);
		}
	}
